    if resources:
        best = None
        for r in resources:
            sd = cheb((sx, sy), r)
            od = cheb((ox, oy), r)
            adv = od - sd  # larger => we are closer
            # tie-break deterministically: smaller sd, then x,y
            cand = (-(adv), sd, r[0], r[1])
            if best is None or cand < best:
                best = cand
        tx, ty = best[2], best[3]
    else:
